// Explicit, cancellable forms replace browser-native prompts.
let pendingForm = null;
const modalRoot = document.getElementById('modal');
let flashTimer=null;
function flashHint(message,delay=3500){if(flashTimer)clearTimeout(flashTimer);hint(message);flashTimer=setTimeout(()=>{let box=document.getElementById('hint');if(box.textContent===message)hint('')},delay)}
function formatRate(value){if(value===null||value===undefined)return'—';let n=Number(value),units=['bps','Kbps','Mbps','Gbps','Tbps'],i=0;while(Math.abs(n)>=1000&&i<units.length-1){n/=1000;i++}return`${n.toLocaleString('pt-BR',{maximumFractionDigits:i?2:0})} ${units[i]}`}
function formatDistance(value){let n=Number(value);if(!Number.isFinite(n))return'—';return n>=1000?`${(n/1000).toLocaleString('pt-BR',{maximumFractionDigits:2})} km`:`${Math.round(n).toLocaleString('pt-BR')} m`}
function formatCollected(clock){return clock?new Date(Number(clock)*1000).toLocaleString('pt-BR'):'Sem coleta'}
function formatDbm(value){return value===null||value===undefined?'—':`${Number(value).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2})} dBm`}
function statusText(status){return status==='up'?'Operacional (UP)':status==='down'?'Inoperante (DOWN)':status==='provisional'?'Enlace provisório':'Desconhecido'}
function filterInterfaceCards(selector,term){term=term.trim().toLocaleLowerCase('pt-BR');document.querySelectorAll(selector).forEach(card=>{card.style.display=!term||card.textContent.toLocaleLowerCase('pt-BR').includes(term)?'block':'none'})}
function filterInterfaceSelects(selector,interfaces,term){term=term.trim().toLocaleLowerCase('pt-BR');document.querySelectorAll(selector).forEach(select=>{let current=select.value,matches=interfaces.map((item,index)=>({item,index})).filter(({item})=>!term||`${item.name} ${item.description||''}`.toLocaleLowerCase('pt-BR').includes(term));select.replaceChildren(...matches.map(({item,index})=>new Option(`${item.name} — ${item.description||'Sem descrição'} · ${statusText(item.status)}`,String(index))));if(matches.some(({index})=>String(index)===current))select.value=current})}
function interfaceMetrics(x){let statusLabel=x.status_source==='ponStatus'?'Status da PON':'Status operacional';return`<div class="iface-metrics"><div><span>${statusLabel}</span><b class="${x.status==='up'?'updot':x.status==='down'?'downdot':'unkdot'}">${esc(statusText(x.status))}</b><small>${esc(formatCollected(x.status_clock))}</small></div><div><span>Download · tráfego de entrada/RX</span><b>${esc(formatRate(x.download_bps))}</b><small>${esc(formatCollected(x.download_clock))}</small></div><div><span>Upload · tráfego de saída/TX</span><b>${esc(formatRate(x.upload_bps))}</b><small>${esc(formatCollected(x.upload_clock))}</small></div><div><span>Potência óptica RX</span><b>${esc(formatDbm(x.optical_rx_dbm))}</b><small>${esc(formatCollected(x.optical_rx_clock))}</small></div><div><span>Potência óptica TX</span><b>${esc(formatDbm(x.optical_tx_dbm))}</b><small>${esc(formatCollected(x.optical_tx_clock))}</small></div></div>`}
const extraStyle=document.createElement('style');
