async function selectTargetMappings(d,sources){
 if(!d.zabbix_hostid){if(d.kind==='cto')return selectCtoTargetMappings(d,sources);return sources.map(source=>({source,target:endpoint(d)}))}let xs=[];try{xs=await api(`/api/interfaces/${d.zabbix_hostid}`)}catch(error){xs=[]}closeModal();return new Promise(resolve=>{pendingForm=resolve;let selected=sources.map((_,i)=>xs.length?Math.min(i,xs.length-1):-1);function finish(){if(selected.some(i=>!Number.isInteger(i)||i>=xs.length))return;let real=selected.filter(i=>i>=0),unique=new Set(real);if(unique.size!==real.length){document.getElementById('targetMappingError').textContent='Cada enlace deve usar uma interface de destino diferente.';return}resolveForm(sources.map((source,i)=>{let target=endpoint(d),x=selected[i]>=0?xs[selected[i]]:null;if(x){target.interface_itemid=x.status_itemid;target.interface_name=x.name;target.interface_description=x.description}return{source,target}}))}function picker(index){modal(`Escolher interface de destino — ${d.name}`,`<input id="targetPickerSearch" autofocus placeholder="Digite para buscar porta ou descrição"><div id="targetPickerChoices"></div><button id="backToTargetMappings">Voltar</button>`);let input=document.getElementById('targetPickerSearch'),choices=document.getElementById('targetPickerChoices');function renderChoices(){let term=input.value.trim().toLocaleLowerCase('pt-BR'),matches=xs.map((x,i)=>({x,i})).filter(({x})=>`${x.name} ${x.description||''}`.toLocaleLowerCase('pt-BR').includes(term));choices.innerHTML=matches.map(({x,i})=>`<button class="iface target-picker-choice" data-i="${i}"><b class="${x.status==='up'?'updot':x.status==='down'?'downdot':'unkdot'}">●</b> ${esc(x.name)}<br><small>${esc(x.description||'Sem descrição')} · ${esc(statusText(x.status))}</small></button>`).join('')+`<button class="iface target-picker-choice provisional-interface" data-i="-1"><b>Enlace provisório</b><br><small>Não vincular uma interface de destino agora.</small></button>`;choices.querySelectorAll('.target-picker-choice').forEach(button=>button.onclick=()=>{selected[index]=Number(button.dataset.i);render()})}input.oninput=renderChoices;document.getElementById('backToTargetMappings').onclick=render;renderChoices();input.focus()}function render(){modal(`Interfaces de destino — ${d.name}`,`<p>Associe cada interface do host de origem a uma interface deste host.</p><div>${sources.map((source,i)=>`<div class="link-side"><b>${esc(source.interface_name||'Enlace provisório')}</b><small> no host de origem</small><label>Conectar em</label><button class="target-picker iface" data-i="${i}">${selected[i]<0?'<b>Enlace provisório</b> · sem interface de destino':`${esc(xs[selected[i]].name)} — ${esc(xs[selected[i]].description||'Sem descrição')} · ${esc(statusText(xs[selected[i]].status))}`}</button></div>`).join('')}</div><p id="targetMappingError" class="form-error"></p><button id="continueTargets" class="primary">Prosseguir</button>`);document.querySelectorAll('.target-picker').forEach(button=>button.onclick=()=>picker(Number(button.dataset.i)));document.getElementById('continueTargets').onclick=finish}render()});
}
drawPreview=function(cursor){if(preview)map.removeLayer(preview);if(!draft)return;let pts=draft.points.map(p=>[p[1],p[0]]);if(cursor)pts.push(cursor);preview=L.polyline(pts,{color:'#0284c7',weight:4,dashArray:'6 5',interactive:false}).addTo(map);};
finishTarget=async function(m){
 if(!draft||!['route','target'].includes(mode))return;
 let current=draft,p=m.getLatLng();if(current.source.kind===endpoint(m.net).kind&&current.source.id===m.net.id){hint('Escolha outro elemento como destino.');return;}
 mode='selecting';
 try{let mappings=await selectTargetMappings(m.net,current.sources||[current.source]);if(!mappings||draft!==current){if(draft===current)mode='route';return;}let routeMode=current.points.length===1?await routeModeForm():'manual';if(!routeMode||draft!==current){if(draft===current)mode='route';return;}let coordinates=[...current.points,[p.lng,p.lat]];if(routeMode==='suggested'){hint('Calculando trajeto pelas ruas…');let route=await api('/api/routes/suggest',{method:'POST',body:JSON.stringify({source:coordinates[0],target:coordinates[coordinates.length-1]})});coordinates=route.coordinates;}let defaultName=`${current.source.name} → ${mappings[0].target.name}`,name=await nameForm(mappings.length>1?'Salvar enlaces':'Salvar enlace',defaultName,mappings.length>1?`Salvar ${mappings.length} enlaces`:'Salvar enlace');if(!name||draft!==current){if(draft===current)mode='route';return;}mode='saving';let parents=links.filter(l=>l.target_kind===current.source.kind&&Number(l.target_id)===Number(current.source.id)),parent=parents.length===1?parents[0].id:null,group=current.trunk?`eth-${Date.now()}-${Math.random().toString(36).slice(2,8)}`:null,payloads=mappings.map(({source,target},i)=>({name:mappings.length===1?name:`${name} · ${source.interface_name||source.name} → ${target.interface_name||target.name}`,source,target,parent_link_id:parent,coordinates,route_mode:routeMode,trunk_group:group,is_trunk:Boolean(group&&i===0)}));await api('/api/links/bulk',{method:'POST',body:JSON.stringify({links:payloads})});cancel();await loadLinks();flashHint(`${payloads.length} enlace${payloads.length===1?' salvo':'s salvos'} com sucesso.`);}
 catch(e){mode='route';hint(`Não foi possível salvar o enlace: ${e.message}. O desenho foi preservado.`);}
};
