map.off('click');map.on('click',e=>{if(mode==='host-position'){openZabbixHostSearch(e.latlng);return;}if(mode==='provisional-host'){createElementAt('host',e.latlng);return;}if(mode==='cto'){createElementAt('cto',e.latlng);return;}if(mode==='route'||mode==='target'){draft.points.push([e.latlng.lng,e.latlng.lat]);mode='route';drawPreview();hint('Continue o trajeto ou clique no destino.');}});
