async function deleteCtoConfirmed(m){
 let connected=links.filter(l=>(l.source_kind==='node'&&Number(l.source_id)===Number(m.net.id))||(l.target_kind==='node'&&Number(l.target_id)===Number(m.net.id))).length;
 let warning=connected?` A exclusão também removerá ${connected} enlace${connected===1?'':'s'} conectado${connected===1?'':'s'} a ela.`:' Ela não possui enlaces conectados.';
 let ok=await confirmForm('Excluir CTO',`Deseja excluir definitivamente a CTO “${m.net.name}”?${warning}`,'Excluir CTO');if(!ok)return;
 try{hint('Excluindo CTO no NetAtlas e no NetBox…');let result=await api(`/api/nodes/${m.net.id}`,{method:'DELETE'});closePanel();closeLinkDialog();map.closePopup();await Promise.all([loadNodes(),loadLinks(),loadIssues(false)]);flashHint(`CTO excluída com sucesso${result.removed_links?` · ${result.removed_links} enlace${result.removed_links===1?' removido':'s removidos'}`:''}.`,5000)}catch(e){flashHint(`Não foi possível excluir a CTO: ${e.message}`,6000)}
}
async function deleteHostConfirmed(m){
 let connected=links.filter(l=>(l.source_kind==='device'&&Number(l.source_id)===Number(m.net.id))||(l.target_kind==='device'&&Number(l.target_id)===Number(m.net.id))).length;
 let warning=connected?` A exclusão também removerá ${connected} enlace${connected===1?'':'s'} conectado${connected===1?'':'s'} a ele.`:' Ele não possui enlaces conectados.';
 let ok=await confirmForm('Excluir Host',`Deseja excluir definitivamente o host “${m.net.name}”? O equipamento e as interfaces serão removidos do NetBox.${warning}`,'Excluir Host');if(!ok)return;
 try{hint('Excluindo host no NetAtlas e no NetBox…');let result=await api(`/api/devices/${m.net.id}`,{method:'DELETE'});closePanel();map.closePopup();map.removeLayer(m);markers.delete(`device:${m.net.id}`);await Promise.all([loadLinks(),loadIssues(false)]);flashHint(`Host excluído com sucesso${result.removed_links?` · ${result.removed_links} enlace${result.removed_links===1?' removido':'s removidos'}`:''}.`,5000)}catch(e){flashHint(`Não foi possível excluir o host: ${e.message}`,6000)}
}

async function deleteLinkConfirmed(l){
 let ok=await confirmForm('Excluir enlace',`Deseja excluir o enlace “${l.name}”?`,'Excluir enlace');
 if(!ok)return;
 try{hint('Excluindo enlace…');await api(`/api/links/${l.id}`,{method:'DELETE'});closeLinkDialog();await loadLinks();flashHint('Enlace excluído com sucesso.');}
 catch(e){hint(`Não foi possível excluir o enlace: ${e.message}`);}
}
async function replaceLinkInterface(l,side){
 let host=l[`${side}_zabbix_hostid`];if(!host){flashHint('Esta ponta não possui um host monitorado no Zabbix.',5000);return}
 let selected=await selectInterface({kind:'device',id:l[`${side}_id`],name:l[`${side}_name`],zabbix_hostid:host},side==='source'?'host 1':'host 2');if(!selected)return;
 try{await api(`/api/links/${l.id}/interface/${side}`,{method:'PATCH',body:JSON.stringify({interface_itemid:selected.interface_itemid,interface_name:selected.interface_name,interface_description:selected.interface_description})});await loadLinks();let updated=links.find(x=>Number(x.id)===Number(l.id)),updatedLayer=linkLayers.get(Number(l.id));if(updated&&updatedLayer)await openLinkPanel(updated,updatedLayer);flashHint(`Interface do ${side==='source'?'host 1':'host 2'} substituída com sucesso.`)}catch(e){flashHint(`Não foi possível substituir a interface: ${e.message}`,5000)}
}
async function insertCtoAtLink(l,latlng){
 if(!latlng){flashHint('Clique novamente no ponto exato do enlace onde deseja inserir a CTO.',5000);return}
 let name=await nameForm('Inserir CTO no enlace','','Continuar');if(!name)return;let splitter=await splitterForm(name,'passagem');if(splitter===undefined)return;
 let inputSide=null;if(splitter){inputSide=await new Promise(resolve=>{pendingForm=resolve;modal('Entrada do splitter',`<p>Escolha qual lado do enlace alimenta a entrada do splitter.</p><button class="iface cto-input-side" data-side="source"><b>${esc(l.source_name)}</b><br><small>${esc(l.source_interface_name||'Sem interface')} → entrada do splitter</small></button><button class="iface cto-input-side" data-side="target"><b>${esc(l.target_name)}</b><br><small>${esc(l.target_interface_name||'Sem interface')} → entrada do splitter</small></button>`);document.querySelectorAll('.cto-input-side').forEach(button=>button.onclick=()=>resolveForm(button.dataset.side))});if(!inputSide)return}
 try{hint('Salvando a CTO no NetAtlas e no NetBox…');let result=await api(`/api/links/${l.id}/insert-cto`,{method:'POST',body:JSON.stringify({name,latitude:latlng.lat,longitude:latlng.lng,splitter_type:splitter,input_side:inputSide})});closeLinkDialog();await Promise.all([loadNodes(),loadLinks()]);map.setView([result.latitude,result.longitude],Math.max(17,map.getZoom()));flashHint(`CTO inserida no enlace${splitter?` com splitter ${splitter.replace('x','×')}`:' sem splitter'}.`)}catch(e){flashHint(`Não foi possível inserir a CTO: ${e.message}`,6000)}
}
async function insertLagsInTrunk(l){
 let sourceHost={kind:'device',id:l.source_id,name:l.source_name,zabbix_hostid:l.source_zabbix_hostid};
 let xs=await api(`/api/interfaces/${sourceHost.zabbix_hostid}`),trunkItem=Number(l.source_interface_itemid),trunkName=l.source_interface_name;
 let chosen=await new Promise(resolve=>{pendingForm=resolve;modal('Inserir LAGs na Eth-Trunk',`<p><b>${esc(trunkName||'Interface principal')}</b> será o tubo principal. As LAGs usarão automaticamente a interface de destino já configurada no enlace.</p><input id="lagSourceSearch" placeholder="Buscar LAG por porta ou descrição"><div id="lagSourceChoices">${xs.filter(x=>Number(x.status_itemid)!==trunkItem&&x.name!==trunkName).map((x,i)=>`<label class="iface"><input type="checkbox" data-i="${i}" style="width:auto;margin:0 8px 0 0"><b class="${x.status==='up'?'updot':x.status==='down'?'downdot':'unkdot'}">●</b> ${esc(x.name)}<br><small>${esc(x.description||'Sem descrição')}</small></label>`).join('')||'<p>Nenhuma outra interface disponível.</p>'}</div><p id="lagChoiceError" class="form-error"></p><button id="continueLags" class="primary">Inserir LAGs</button>`);document.getElementById('lagSourceSearch').oninput=e=>filterInterfaceCards('#lagSourceChoices .iface',e.target.value);document.getElementById('continueLags').onclick=()=>{let available=xs.filter(x=>Number(x.status_itemid)!==trunkItem&&x.name!==trunkName),selected=[...document.querySelectorAll('#lagSourceChoices input:checked')].map(c=>available[Number(c.dataset.i)]);if(!selected.length){document.getElementById('lagChoiceError').textContent='Selecione ao menos uma interface LAG.';return}resolveForm(selected)}});
 if(!chosen)return;
 let sources=chosen.map(x=>({kind:'device',id:sourceHost.id,name:sourceHost.name,zabbix_hostid:sourceHost.zabbix_hostid,interface_itemid:x.status_itemid,interface_name:x.name,interface_description:x.description}));
 try{let result=await api(`/api/links/${l.id}/lags`,{method:'POST',body:JSON.stringify({members:sources.map(source=>({source}))})});closeLinkDialog();await loadLinks();flashHint(`${result.count} LAG${result.count===1?' inserida':'s inseridas'} na Eth-Trunk.`,5000)}catch(e){flashHint(`Não foi possível inserir as LAGs: ${e.message}`,6000)}
}
function lockLinkEndpoints(layer){setTimeout(()=>{for(let handler of layer.editing?._verticesHandlers||[]){let vertices=handler._markers||[];for(let marker of [vertices[0],vertices[vertices.length-1]])if(marker){marker.dragging?.disable();marker.setOpacity?.(.65);marker._icon&&(marker._icon.title='Ponta fixa no host')}}},0)}
function lockedLinkCoordinates(link,layer){let points=layer.getLatLngs().slice(),original=link.geometry.coordinates;if(points.length>=2&&original.length>=2){points[0]=L.latLng(original[0][1],original[0][0]);let last=original[original.length-1];points[points.length-1]=L.latLng(last[1],last[0])}return points.map(p=>[p.lng,p.lat])}
openLinkPanel=async function(l,layer,clickedLatLng=null){
 if(clickedLatLng)l._clickedLatLng=clickedLatLng;
 showLinkDialog(`<h2>${esc(l.name)}</h2><div class="panel-meta">Carregando informações das interfaces…</div>`);
 let sides=await Promise.all(['source','target'].map(async side=>{let host=l[`${side}_zabbix_hostid`],item=l[`${side}_interface_itemid`];if(!host)return null;try{let xs=await api(`/api/interfaces/${host}`);return xs.find(x=>Number(x.status_itemid)===Number(item))||xs.find(x=>x.name===l[`${side}_interface_name`])||null}catch(e){return{error:e.message}}}));
 let trunkLags=[];if(l.is_trunk&&l.trunk_group&&l.source_zabbix_hostid){try{let xs=await api(`/api/interfaces/${l.source_zabbix_hostid}`);trunkLags=links.filter(x=>x.trunk_group===l.trunk_group&&!x.is_trunk).map(member=>({member,iface:xs.find(x=>Number(x.status_itemid)===Number(member.source_interface_itemid))||xs.find(x=>x.name===member.source_interface_name)}))}catch(e){trunkLags=[]}
 }
 let sideCard=(side,x,extra='')=>{let title=l[`${side}_name`],provisional=l[`${side}_kind`]==='device'&&!l[`${side}_interface_itemid`]&&!l[`${side}_interface_name`],iface=provisional?'Enlace provisório':l[`${side}_interface_name`]||'Sem interface',state=provisional?'provisional':x?.status||'unknown',stateLabel=provisional?'Sem interface vinculada':l[`${side}_zabbix_hostid`]?(state==='down'?'Offline':statusText(state)):'Elemento passivo',content;if(provisional)content='<small>Esta ponta ainda não está vinculada a uma interface. O estado do enlace depende somente das demais interfaces configuradas.</small>';else if(!l[`${side}_zabbix_hostid`])content='<small>Elemento sem monitoramento no Zabbix.</small>';else if(x&&x.error)content=`<small>Falha na coleta: ${esc(x.error)}</small>`;else if(!x)content='<small>Interface não localizada no Zabbix.</small>';else content=`<p><small>${esc(x.description||'Sem descrição')}</small></p>${interfaceMetrics(x)}`;return`<details class="link-endpoint"><summary><span class="endpoint-ident"><strong>${esc(title)}</strong><small>${esc(iface)}</small></span><span class="endpoint-controls"><b class="endpoint-status ${state==='up'?'updot':state==='down'?'downdot':'unkdot'}">● ${esc(stateLabel)}</b><span class="endpoint-open"></span></span></summary><div class="link-endpoint-body">${content}${extra}</div></details>`};
 let splitterLabel=value=>value?`Splitter ${value.replace('x','×')}`:'Sem splitter';let sourceSplitter=l.source_kind==='node'&&l.source_splitter_type?`<small>${esc(splitterLabel(l.source_splitter_type))}</small>`:'',targetSplitter=l.target_kind==='node'&&l.target_splitter_type?`<small>${esc(splitterLabel(l.target_splitter_type))}</small>`:'';let passiveList=(l.passive_nodes||[]).length?`<section class="link-side"><h3>CTOs / elementos no caminho</h3><ol>${l.passive_nodes.map(n=>`<li>${esc(n.name)} <small>· ${esc(splitterLabel(n.splitter_type))}</small></li>`).join('')}</ol></section>`:'';
 let lagList=trunkLags.length?`<section><h4>LAGs da Trunk</h4>${trunkLags.map(({member,iface})=>`<details class="trunk-lag"><summary><b class="${member.status==='up'?'updot':member.status==='down'?'downdot':'unkdot'}">●</b> ${esc(member.source_interface_name||'LAG')} <small>→ ${esc(member.target_interface_name||'destino da Trunk')}</small></summary>${iface?interfaceMetrics(iface):'<small>Interface não localizada no Zabbix.</small>'}</details>`).join('')}</section>`:'';
 let lagButton=l.source_zabbix_hostid&&l.target_zabbix_hostid?`<button id="insertTrunkLags" class="panel-action">${l.is_trunk?'Inserir LAGs':'Tornar Eth-Trunk e inserir LAGs'}</button>`:'';
 let flow=`<div class="link-flow ${l.status}" aria-label="${esc(statusText(l.status))}">${l.status==='up'?'<i class="flow-particle"></i><i class="flow-particle reverse"></i>':''}</div>`;
 showLinkDialog(`<h2>${esc(l.name)}</h2><div class="panel-meta">Status do enlace: <b class="${l.status==='up'?'updot':l.status==='down'?'downdot':'unkdot'}">${esc(statusText(l.status))}</b> · Extensão: <b>${esc(formatDistance(l.length_m))}</b>${l.is_trunk?' · <span class="suggested-route-label">Eth-Trunk</span>':l.route_mode==='suggested'?' · <span class="suggested-route-label">Trajeto sugerido</span>':l.route_mode==='straight'?' · Linha reta':''}</div><div class="link-flow-layout">${sideCard('source',sides[0],`${sourceSplitter}${lagList}`)}${flow}${sideCard('target',sides[1],targetSplitter)}</div>${passiveList}<div class="link-actions">${l.source_zabbix_hostid?'<button id="replaceSourceInterface" class="panel-action">Trocar interface do host 1</button>':''}${l.target_zabbix_hostid?'<button id="replaceTargetInterface" class="panel-action">Trocar interface do host 2</button>':''}${lagButton}<button id="insertCtoInLink" class="panel-action">Inserir CTO neste ponto</button><button id="renameLink" class="panel-action">Renomear enlace</button><button id="editLink" class="panel-action">Editar trajeto</button><button id="deleteLink" class="panel-action danger">Excluir enlace</button></div><div id="linkEditActions"></div>`);
 let replaceSource=document.getElementById('replaceSourceInterface'),replaceTarget=document.getElementById('replaceTargetInterface'),insertLags=document.getElementById('insertTrunkLags');if(replaceSource)replaceSource.onclick=()=>replaceLinkInterface(l,'source');if(replaceTarget)replaceTarget.onclick=()=>replaceLinkInterface(l,'target');if(insertLags)insertLags.onclick=()=>insertLagsInTrunk(l);document.getElementById('insertCtoInLink').onclick=()=>insertCtoAtLink(l,l._clickedLatLng||clickedLatLng);
 document.getElementById('renameLink').onclick=async()=>{let name=await nameForm('Renomear enlace',l.name,'Salvar novo nome');if(!name)return;try{await api(`/api/links/${l.id}/name`,{method:'PATCH',body:JSON.stringify({name})});closeLinkDialog();await loadLinks();flashHint('Enlace renomeado com sucesso.')}catch(e){flashHint(`Não foi possível renomear: ${e.message}`,5000)}};
 document.getElementById('editLink').onclick=()=>{closeLinkDialog();layer.editing.enable();lockLinkEndpoints(layer);showPanel(`<h2>Editar trajeto</h2><p>Mova somente os pontos intermediários. As duas pontas permanecem presas aos hosts.</p><div id="linkEditActions"><button id="saveLink" class="panel-action">Salvar novo trajeto</button><button id="cancelLinkEdit" class="panel-action">Cancelar edição</button></div>`);document.getElementById('saveLink').onclick=async()=>{try{await api(`/api/links/${l.id}`,{method:'PUT',body:JSON.stringify({coordinates:lockedLinkCoordinates(l,layer)})});layer.editing.disable();closePanel();await loadLinks();flashHint('Trajeto atualizado.')}catch(e){hint(`Não foi possível salvar: ${e.message}`)}};document.getElementById('cancelLinkEdit').onclick=()=>{layer.editing.disable();closePanel();loadLinks()}};
 document.getElementById('deleteLink').onclick=()=>deleteLinkConfirmed(l);
};
loadLinks=async function(){
 links=await api('/api/links');editable.clearLayers();
 links.forEach(l=>{let state=l.status==='up'?'up':l.status==='down'?'down':'unknown',layer=L.polyline(l.geometry.coordinates.map(p=>[p[1],p[0]]),{color:lineColor(l.status),weight:5,className:`net-link net-link-${state}`,bubblingMouseEvents:false});layer.linkId=l.id;layer.on('click',e=>{openLinkPanel(l,layer)});layer.on('contextmenu',e=>{if(e.originalEvent)L.DomEvent.preventDefault(e.originalEvent);if(mode)return;let popup=L.popup({closeButton:true}).setLatLng(e.latlng).setContent(`<div class="link-menu"><b>${esc(l.name)}</b><button id="openLinkDetails">Abrir detalhes</button><button id="removeLinkHere" class="danger">Excluir enlace</button></div>`).openOn(map);setTimeout(()=>{let open=document.getElementById('openLinkDetails'),remove=document.getElementById('removeLinkHere');if(open)open.onclick=()=>{map.closePopup(popup);openLinkPanel(l,layer)};if(remove)remove.onclick=()=>{map.closePopup(popup);deleteLinkConfirmed(l)}},0)});editable.addLayer(layer)});
};
